package com.angle.trading.controller;import lombok.extern.slf4j.Slf4j;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.RequestMapping;import java.time.LocalDateTime;@Controller@RequestMapping("/dashboard")@Slf4jpublic class DashboardController {    @GetMapping    public String home(Model model, Authentication authentication) {        LocalDateTime sessionStart =LocalDateTime.now().withNano(0);        log.info("User '{}' logged in at {}",                authentication.getName(), sessionStart);        model.addAttribute("user", authentication.getName());        model.addAttribute("sessionStart", sessionStart);        return "dashboard/welcome";    }}